                if (existing !== undefined && isActive) {
                    setValue(existing);
                    valueRef.current = existing;
                }
            });
            void client.subscribe(key, handleUpdate);
            const unsubscribeStatus = options.onStatusChange
                ? onStatusChange(resolvedUrl, options.onStatusChange)
                : undefined;
